(()=>{'use strict';const node=document.getElementById('family-portraits-data');if(!node)return;let data=JSON.parse(node.textContent);const $=id=>document.getElementById(id),dialog=$('family-profile');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let opener=null;function filter(){const q=$('family-name-search').value.trim().toLocaleLowerCase('it'),group=$('family-collection').value,photoOnly=$('family-only-photos').checked;let count=0;document.querySelectorAll('.family-portrait-card').forEach(card=>{const p=data.find(p=>p.id===card.dataset.profile),match=(!photoOnly||p.photo)&&(!group||p.collection===group)&&(!q||(p.name+' '+p.aliases.join(' ')).toLocaleLowerCase('it').includes(q));card.hidden=!match;if(match)count++});$('family-result-count').textContent=count+' schede visibili';}function show(id){const p=data.find(p=>p.id===id);if(!p)return;const image=p.photo_full?`<a class="family-profile-image" href="${esc(p.photo_full)}" target="_blank" rel="noopener"><img src="${esc(p.photo_full)}" alt="Ritratto di ${esc(p.name)}"><span>Apri il ritratto ↗</span></a>`:'<div class="family-profile-no-photo">Fotografia non disponibile</div>';const dates=`<dl class="family-profile-dates"><dt>Nascita</dt><dd>${esc(p.birth||'Data non riportata')}</dd>${p.birth_place?'<dt>Luogo di nascita</dt><dd>'+esc(p.birth_place)+'</dd>':''}${p.death||p.deceased_recorded?'<dt>Morte</dt><dd>'+esc(p.death||'Il documento indica il decesso, senza data.')+'</dd>':''}</dl>`;const alias=p.aliases.length?'<p>Conosciuto anche come: '+esc(p.aliases.join(', '))+'</p>':'';const links=p.tree_ids.map(id=>{const tree=id.startsWith('antenati')?'antenati':'discendenti';return `<button type="button" data-profile-tree="${id}" data-target-tree="${tree}">Mostra nell’albero ${tree==='antenati'?'degli antenati':'dei discendenti'}</button>`}).join('');$('family-profile-content').innerHTML=`<div class="family-profile-layout">${image}<div><p class="eyebrow">RACCOLTA ${esc(p.collection)}</p><h2 id="family-profile-title">${esc(p.name)}</h2>${alias}${dates}${p.notes?'<p class="family-source-note">'+esc(p.notes).replace(/\n/g,'<br>')+'</p>':''}${p.identity_note?'<p class="family-source-note">'+esc(p.identity_note)+'</p>':''}<p class="family-source-note">${esc(p.source)}</p>${p.source_pdf?'<a href="'+esc(p.source_pdf)+'" target="_blank" rel="noopener">Albero familiare di riferimento ↗</a>':''}<div class="family-tree-links">${links}</div></div></div>`;dialog.setAttribute('aria-labelledby','family-profile-title');dialog.showModal();}document.querySelector('.family-portrait-grid').addEventListener('click',e=>{const b=e.target.closest('[data-profile]');if(b){opener=b;show(b.dataset.profile)}});$('close-family-profile').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus({preventScroll:true}));dialog.addEventListener('click',e=>{const b=e.target.closest('[data-profile-tree]');if(!b)return;dialog.close();const tree=document.querySelector('[data-tree="'+b.dataset.targetTree+'"]');tree?.click();document.querySelector('#tree-canvas [data-person="'+b.dataset.profileTree+'"]')?.click();});$('family-name-search').addEventListener('input',filter);$('family-collection').addEventListener('change',filter);$('family-only-photos').addEventListener('change',filter);window.addEventListener('family-genealogy-updated',e=>{data=e.detail.profiles;document.querySelector('.family-portrait-grid').innerHTML=data.map(p=>`<button type="button" class="family-portrait-card" data-profile="${esc(p.id)}">${p.photo?`<img src="${esc(p.photo)}" alt="" loading="lazy">`:'<span class="family-no-photo">Foto non disponibile</span>'}<span class="family-card-copy"><strong>${esc(p.name)}</strong><span class="family-card-dates">Nascita: ${esc(p.birth||'data non indicata')}${p.birth_place?'<br>'+esc(p.birth_place):''}</span><span class="family-card-open">Apri la scheda →</span></span></button>`).join('');const value=$('family-collection').value;const select=$('family-collection');select.replaceChildren(new Option('Tutte le raccolte',''),...[...new Set(data.map(p=>p.collection))].sort().map(c=>new Option(c,c)));select.value=value;filter();});filter();})();
